-- A permissive historic policy cannot expose comments after the restrictive policy.
select set_config('request.jwt.claims','{"sub":"dddddddd-dddd-4ddd-8ddd-dddddddddddd","role":"authenticated"}',false);
set role authenticated;
select public.test_assert((select count(*)=0 from public.ratings),'driver cannot read private comments');
reset role;
select set_config('request.jwt.claims','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',false);
set role authenticated;
select public.test_assert((select count(*)=1 from public.ratings),'admin can read private comments');
reset role;
select 'PASS: commercial SQL checks';
